import {
    createProject,
    createTestContext,
    FluentXmlFluentTest,
    runTestOnFunction,
    validateDiagnostic,
} from '../test-utils'
import { ts } from '@servicenow/sdk-build-core'

describe('Email Notification Plugin', () => {
    const ctx = createTestContext({
        rootDir: __dirname,
    })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    describe('Diagnostics', () => {
        test('Error when engine type has neither onRecordInsert nor onRecordUpdate', async () => {
            const project = ctx.createProject({
                rootDir: __dirname,
                config: { fluentDir: 'project/fluent', serverModulesDir: 'project/server' },
            })

            project.registerExplicitId('sysevent_email_action', 'invalid_notification')

            const file = project.addFile({
                path: 'invalid-notification.now.ts',
                content: `
import { EmailNotification } from '@servicenow/sdk/core'

EmailNotification({
    $id: Now.ID['invalid_notification'],
    table: 'incident',
    name: 'Invalid Notification',
    category: 'c97d83137f4432005f58108c3ffa917a',
    triggerConditions: {
        generationType: 'engine',
        onRecordInsert: false,
        onRecordUpdate: false,
    },
    recipientDetails: {
        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
    },
    emailContent: {
        subject: 'Test',
        messageHtml: 'Test message',
    },
})
                `,
            })

            const diagnostics = await file.getDiagnostics()
            expect(diagnostics).toHaveLength(1)
            validateDiagnostic(
                diagnostics,
                ts.SyntaxKind.ObjectLiteralExpression,
                "When triggerConditions.generationType is 'engine', at least one of 'onRecordInsert' or 'onRecordUpdate' must be true."
            )
        })

        test('Warning when HTML content type is missing messageHtml', async () => {
            const project = ctx.createProject({
                config: { fluentDir: 'project/fluent', serverModulesDir: 'project/server' },
            })
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                EmailNotification({
                    $id: 'html_missing_content',
                    table: 'incident',
                    name: 'HTML Missing Content',
                    triggerConditions: {
                        generationType: 'engine',
                        onRecordInsert: true,
                    },
                    recipientDetails: {
                        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
                    },
                    emailContent: {
                        contentType: 'text/html',
                        subject: 'Test',
                    },
                })
            })
            expect(output.length).toBeGreaterThan(0)
            const warning = output.find((d) =>
                d.message.includes("Content type is 'text/html' but 'messageHtml' is not provided")
            )
            expect(warning).toBeDefined()
        })

        test('Warning when HTML content type has messageText (will be ignored)', async () => {
            const project = ctx.createProject()
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                EmailNotification({
                    $id: 'html_with_text',
                    table: 'incident',
                    name: 'HTML with Text',
                    triggerConditions: {
                        generationType: 'engine',
                        onRecordInsert: true,
                    },
                    recipientDetails: {
                        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
                    },
                    emailContent: {
                        contentType: 'text/html',
                        subject: 'Test',
                        messageHtml: '<p>HTML content</p>',
                        messageText: 'This will be ignored',
                    },
                })
            })
            expect(output.length).toBeGreaterThan(0)
            const warning = output.find((d) =>
                d.message.includes("Content type is 'text/html': 'messageText' will be ignored")
            )
            expect(warning).toBeDefined()
        })

        test('Warning when plain text content type is missing messageText', async () => {
            const project = ctx.createProject()
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                EmailNotification({
                    $id: 'text_missing_content',
                    table: 'incident',
                    name: 'Text Missing Content',
                    triggerConditions: {
                        generationType: 'engine',
                        onRecordInsert: true,
                    },
                    recipientDetails: {
                        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
                    },
                    emailContent: {
                        contentType: 'text/plain',
                        subject: 'Test',
                    },
                })
            })
            expect(output.length).toBeGreaterThan(0)
            const warning = output.find((d) =>
                d.message.includes("Content type is 'text/plain' but 'messageText' is not provided")
            )
            expect(warning).toBeDefined()
        })

        test('Warning when plain text content type has messageHtml (will be ignored)', async () => {
            const project = ctx.createProject()
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                EmailNotification({
                    $id: 'text_with_html',
                    table: 'incident',
                    name: 'Text with HTML',
                    triggerConditions: {
                        generationType: 'engine',
                        onRecordInsert: true,
                    },
                    recipientDetails: {
                        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
                    },
                    emailContent: {
                        contentType: 'text/plain',
                        subject: 'Test',
                        messageText: 'Plain text content',
                        messageHtml: '<p>This will be ignored</p>',
                    },
                })
            })
            expect(output.length).toBeGreaterThan(0)
            const warning = output.find((d) =>
                d.message.includes("Content type is 'text/plain': 'messageHtml' will be ignored")
            )
            expect(warning).toBeDefined()
        })

        test('Warning when multipart content type is missing both messageHtml and messageText', async () => {
            const project = ctx.createProject()
            const output = await runTestOnFunction(project, () => {
                //@ts-expect-error avoid imports
                EmailNotification({
                    $id: 'multipart_missing_content',
                    table: 'incident',
                    name: 'Multipart Missing Content',
                    triggerConditions: {
                        generationType: 'engine',
                        onRecordInsert: true,
                    },
                    recipientDetails: {
                        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
                    },
                    emailContent: {
                        contentType: 'multipart/mixed',
                        subject: 'Test',
                    },
                })
            })
            expect(output.length).toBeGreaterThan(0)
            const warning = output.find((d) =>
                d.message.includes(
                    "Content type is 'multipart/mixed' but neither 'messageHtml' nor 'messageText' is provided"
                )
            )
            expect(warning).toBeDefined()
        })
    })

    describe('Round-trip Tests', () => {
        test('Fluent -> XML -> Fluent: Basic notification with minimal properties', async () => {
            const project = ctx.createProject({
                rootDir: __dirname,
                config: { fluentDir: 'project/fluent', serverModulesDir: 'project/server' },
            })

            const roundTripTest = new FluentXmlFluentTest(project)

            // Register the ID that will be used in the notification
            const notificationId = roundTripTest.addId('sysevent_email_action', 'basic_notification')
            roundTripTest.addExpectedXmlFileNames(`sysevent_email_action_${notificationId}.xml`)

            // Add the Fluent code for a basic email notification
            roundTripTest.addFluentFragment(`
import { EmailNotification } from '@servicenow/sdk/core'

EmailNotification({
    $id: Now.ID['basic_notification'],
    table: 'u_customer_order',
    name: 'Customer Order Notification',
    description: 'Notification sent when a customer order is created or updated',
    category: 'c97d83137f4432005f58108c3ffa917a',
    triggerConditions: {
        generationType: 'engine',
        onRecordInsert: true,
        onRecordUpdate: true,
        condition: 'u_customer_emailISNOTEMPTY^EQ',
        item: 'event.parm1',
    },
    recipientDetails: {
        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
        recipientFields: ['u_customer_email'],
        excludeDelegates: false,
        isSubscribableByAllUsers: false,
        sendToCreator: false,
    },
    emailContent: {
        contentType: 'multipart/mixed',
        subject: 'Order \${u_order_number} - \${u_order_status}',
        message: 'Hello \${u_customer_name}, your order \${u_order_number} has been received.',
        importance: 'high',
        from: 'orders@company.com',
        replyTo: 'support@company.com',
        includeAttachments: false,
        omitWatermark: true,
        pushMessageOnly: false,
        forceDelivery: false,
    },
})
            `)

            await roundTripTest.verify()
        })

        test('Fluent -> XML -> Fluent: Event-based notification', async () => {
            const project = ctx.createProject({
                rootDir: __dirname,
                config: { fluentDir: 'project/fluent', serverModulesDir: 'project/server' },
            })

            const roundTripTest = new FluentXmlFluentTest(project)

            // Register the ID that will be used in the notification
            const notificationId = roundTripTest.addId('sysevent_email_action', 'event_notification')
            roundTripTest.addExpectedXmlFileNames(`sysevent_email_action_${notificationId}.xml`)

            // Add the Fluent code for an event-based email notification
            roundTripTest.addFluentFragment(`
import { EmailNotification } from '@servicenow/sdk/core'

EmailNotification({
    $id: Now.ID['event_notification'],
    table: 'incident',
    name: 'Incident Event Notification',
    description: 'Notification triggered by incident events',
    category: 'c97d83137f4432005f58108c3ffa917a',
    triggerConditions: {
        generationType: 'event',
        eventName: 'incident.inserted',
        weight: 100,
        condition: 'priorityIN1,2',
        item: 'event.parm1',
    },
    recipientDetails: {
        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
        recipientGroups: ['12a586cd0bb23200ecfd818393673a30'],
        excludeDelegates: false,
        isSubscribableByAllUsers: false,
        sendToCreator: false,
        eventParm1WithRecipient: false,
        eventParm2WithRecipient: false,
    },
    emailContent: {
        subject: 'High Priority Incident: \${number}',
        message: 'A high priority incident has been created: \${short_description}',
        includeAttachments: false,
        omitWatermark: false,
        pushMessageOnly: false,
        forceDelivery: false,
    },
})
            `)

            await roundTripTest.verify()
        })

        test('Fluent -> XML -> Fluent: Triggered notification', async () => {
            const project = ctx.createProject({
                rootDir: __dirname,
                config: { fluentDir: 'project/fluent', serverModulesDir: 'project/server' },
            })

            const roundTripTest = new FluentXmlFluentTest(project)

            // Register the ID that will be used in the notification
            const notificationId = roundTripTest.addId('sysevent_email_action', 'triggered_notification')
            roundTripTest.addExpectedXmlFileNames(`sysevent_email_action_${notificationId}.xml`)

            // Add the Fluent code for a triggered email notification
            roundTripTest.addFluentFragment(`
import { EmailNotification } from '@servicenow/sdk/core'

EmailNotification({
    $id: Now.ID['triggered_notification'],
    table: 'task',
    name: 'Manual Task Notification',
    description: 'Notification that can be manually triggered',
    category: 'c97d83137f4432005f58108c3ffa917a',
    triggerConditions: {
        generationType: 'triggered',
        item: 'event.parm1',
    },
    recipientDetails: {
        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
        recipientFields: ['assigned_to'],
        excludeDelegates: false,
        isSubscribableByAllUsers: false,
        sendToCreator: false,
    },
    emailContent: {
        subject: 'Task Update: \${number}',
        message: 'Task \${number} requires your attention: \${short_description}',
        includeAttachments: false,
        omitWatermark: false,
        pushMessageOnly: false,
        forceDelivery: false,
    },
})
            `)

            await roundTripTest.verify()
        })
    })

    describe('XML -> Fluent -> XML Tests', () => {
        test('XML -> Fluent -> XML: Simple round-trip verification', async () => {
            // Step 1: Generate XML from Fluent
            const project1 = createProject({
                rootDir: __dirname,
                config: { fluentDir: 'project/fluent', serverModulesDir: 'project/server' },
            })
            project1.registerExplicitId(
                'sysevent_email_action',
                'xml_test_notification',
                'bb22222222222222222222222222222b'
            )

            const originalFluentContent = `
import { EmailNotification } from '@servicenow/sdk/core'

EmailNotification({
    $id: Now.ID['xml_test_notification'],
    table: 'incident',
    name: 'Simple Incident Notification',
    description: 'A simple test notification',
    category: 'c97d83137f4432005f58108c3ffa917a',
    triggerConditions: {
        generationType: 'engine',
        onRecordInsert: true,
        onRecordUpdate: false,
        item: 'event.parm1',
    },
    recipientDetails: {
        recipientUsers: ['6816f79cc0a8016401c5a33be04be441'],
        excludeDelegates: false,
        isSubscribableByAllUsers: false,
        sendToCreator: false,
    },
    emailContent: {
        subject: 'Incident: \${number}',
        message: 'An incident has been created',
        includeAttachments: false,
        omitWatermark: false,
        pushMessageOnly: false,
        forceDelivery: false,
    },
})
`

            const fluentFile = project1.addFile({
                path: 'notification.now.ts',
                content: originalFluentContent,
            })

            const xmlOutputs = await fluentFile.getOutput()
            expect(xmlOutputs).toHaveLength(1)

            // Step 2: Transform XML back to Fluent
            const project2 = createProject({ rootDir: __dirname })
            project2.registerExplicitId(
                'sysevent_email_action',
                'xml_test_notification',
                'bb22222222222222222222222222222b'
            )

            const { changedFiles } = await project2.transform(xmlOutputs)
            expect(changedFiles).toHaveLength(1)

            // Step 3: Generate XML again from the transformed Fluent
            const regeneratedFluentFile = project2.addFile({
                path: changedFiles[0].getPath(),
                content: changedFiles[0].getContent(),
            })

            const regeneratedXmlOutputs = await regeneratedFluentFile.getOutput()
            expect(regeneratedXmlOutputs).toHaveLength(1)

            // Step 4: Verify key fields match (without full XML diff)
            const originalXml = xmlOutputs[0].content
            const regeneratedXml = regeneratedXmlOutputs[0].content

            // Verify the XML contains the expected key elements
            expect(originalXml).toContain('<name>Simple Incident Notification</name>')
            expect(originalXml).toContain('<collection>incident</collection>')
            expect(originalXml).toContain('<generation_type>engine</generation_type>')
            expect(originalXml).toContain('<action_insert>true</action_insert>')

            expect(regeneratedXml).toContain('<name>Simple Incident Notification</name>')
            expect(regeneratedXml).toContain('<collection>incident</collection>')
            expect(regeneratedXml).toContain('<generation_type>engine</generation_type>')
            expect(regeneratedXml).toContain('<action_insert>true</action_insert>')
        })
    })
})
